  "schema_version": 1,
  "observations": [
    {
      "key": "obs_1",
      "facet": "precondition",
      "statement": "SQLite can determine which index narrows the search to fewer rows only if ANALYZE has been run.",
      "start_line": 1,
      "end_line": 1
    },
    {
      "key": "obs_2",
      "facet": "mechanism",
      "statement": "If all else is equal, SQLite chooses the index that narrows the search to the smallest number of rows, based on statistics from ANALYZE.",
      "start_line": 1,
      "end_line": 1
    },
    {
      "key": "obs_3",
      "facet": "property",
      "statement": "If ANALYZE has not been run, the choice of which index to use is arbitrary.",
      "start_line": 1,
      "end_line": 1
    },
    {
      "key": "obs_4",
      "facet": "mechanism",
      "statement": "A multi-column index uses the left-most column to order rows and later columns to break ties.",
      "start_line": 3,
      "end_line": 3
    },
    {
      "key": "obs_5",
      "facet": "property",
      "statement": "With a suitable multi-column index, SQLite can find a constrained row with fewer searches than with separate lookups.",
      "start_line": 3,
      "end_line": 3
    }
  ],
